CREATE FUNCTION registro_costos_marginales.validar_fecha_real() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- La función make_date() intentará crear la fecha. 
    PERFORM make_date(NEW.año, NEW.mes, NEW.dia);
    
    RETURN NEW;

EXCEPTION 
    -- Capturamos el error específico de desbordamiento de fecha.
    WHEN datetime_field_overflow THEN
        RAISE EXCEPTION 'Operación rechazada: La fecha ingresada (%-%-%) no existe en el calendario real.', NEW.año, NEW.mes, NEW.dia;
END;
$$;


--
-- TOC entry 273 (class 1255 OID 779225)
-- Name: validar_hora_bloque(); Type: FUNCTION; Schema: registro_costos_marginales; Owner: -
--

CREATE FUNCTION registro_costos_marginales.validar_hora_bloque() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

DECLARE
    v_hora_inicio TIME;
    v_hora_fin TIME;
    v_es_valido BOOLEAN := FALSE;
BEGIN
    -- Obtener los límites del bloque horario de la tabla bloque_horario
    SELECT hora_inicio, hora_fin
    INTO v_hora_inicio, v_hora_fin
    FROM registro_costos_marginales.bloque_horario
    WHERE id_bloquehorario = NEW.id_bloquehorario;

    -- Evaluar la hora según si el bloque cruza o no la medianoche
    IF v_hora_inicio <= v_hora_fin THEN
        -- Caso A: Bloque estándar dentro del mismo día (ej. 09:00:00 a 17:59:59)
        IF NEW.hora >= v_hora_inicio AND NEW.hora <= v_hora_fin THEN
            v_es_valido := TRUE;
        END IF;
    ELSE
        -- Caso B: Bloque nocturno que cruza la medianoche (ej. 23:00:00 a 07:00:00)
        IF NEW.hora >= v_hora_inicio OR NEW.hora <= v_hora_fin THEN
            v_es_valido := TRUE;
        END IF;
    END IF;

    -- Si la hora no correspondía al bloque, lanzar excepción
    IF NOT v_es_valido THEN
        RAISE EXCEPTION 'Operación rechazada: La hora % no corresponde al bloque horario (ID: %), el cual abarca desde las % hasta las %.',
            NEW.hora, NEW.id_bloquehorario, v_hora_inicio, v_hora_fin;
    END IF;

    RETURN NEW;
END;
$$;


--
-- TOC entry 270 (class 1255 OID 779217)
-- Name: validar_horario(); Type: FUNCTION; Schema: registro_costos_marginales; Owner: -
--

CREATE FUNCTION registro_costos_marginales.validar_horario() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Un bloque no puede empezar y terminar al mismo tiempo
    IF NEW.hora_inicio = NEW.hora_fin THEN
        RAISE EXCEPTION 'Operación rechazada: La hora de inicio y fin no pueden ser iguales (duración cero).';
    END IF;

    RETURN NEW;
END;
$$;


--
-- TOC entry 272 (class 1255 OID 779222)
-- Name: validar_mes_temporada(); Type: FUNCTION; Schema: registro_costos_marginales; Owner: -
--

CREATE FUNCTION registro_costos_marginales.validar_mes_temporada() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

DECLARE
    v_mes_inicio INT;
    v_mes_fin INT;
    v_nombre_temporada VARCHAR(50);
    v_es_valido BOOLEAN := FALSE;
BEGIN
    -- Obtener los límites del rango de la tabla temporada
    SELECT mes_inicio, mes_fin, nombre_temporada
    INTO v_mes_inicio, v_mes_fin, v_nombre_temporada
    FROM registro_costos_marginales.temporada
    WHERE id_temporada = NEW.id_temporada;

    -- Evaluar el mes según el tipo de rango
    IF v_mes_inicio <= v_mes_fin THEN
        -- Caso A: Temporada estándar (ej. Otoño: 3 al 5)
        IF NEW.mes >= v_mes_inicio AND NEW.mes <= v_mes_fin THEN
            v_es_valido := TRUE;
        END IF;
    ELSE
        -- Caso B: Temporada que cruza de año (ej. Verano: 12 al 2)
        IF NEW.mes >= v_mes_inicio OR NEW.mes <= v_mes_fin THEN
            v_es_valido := TRUE;
        END IF;
    END IF;

    -- Si el mes no correspondía, lanzar excepción
    IF NOT v_es_valido THEN
        RAISE EXCEPTION 'Operación rechazada: El mes % no corresponde a la temporada "%" (ID: %), la cual abarca desde el mes % al %.',
            NEW.mes, v_nombre_temporada, NEW.id_temporada, v_mes_inicio, v_mes_fin;
    END IF;

    RETURN NEW;
END;
$$;


--
-- TOC entry 271 (class 1255 OID 779219)
-- Name: validar_rango_meses(); Type: FUNCTION; Schema: registro_costos_marginales; Owner: -
--

CREATE FUNCTION registro_costos_marginales.validar_rango_meses() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Validar que ambos meses estén en el rango del calendario (1 al 12)
    IF NEW.mes_inicio < 1 OR NEW.mes_inicio > 12 OR NEW.mes_fin < 1 OR NEW.mes_fin > 12 THEN
        RAISE EXCEPTION 'Operación rechazada: Los meses deben estar entre 1 y 12. Valores recibidos: inicio = %, fin = %', NEW.mes_inicio, NEW.mes_fin;
    END IF;

    RETURN NEW;
END;
$$;


